(function(){'use strict';const root=document.getElementById('ko-cha');if(!root)return;
const logo=root.querySelector('.kc-logo-image'),fallback=root.querySelector('.kc-logo-fallback');if(logo&&fallback){const fail=()=>{logo.hidden=true;fallback.hidden=false;};logo.addEventListener('error',fail);if(logo.complete&&!logo.naturalWidth)fail();}
const input=root.querySelector('#menu-search'),clear=root.querySelector('#clear-search'),status=root.querySelector('#search-status'),empty=root.querySelector('#no-results'),groups=[...root.querySelectorAll('[data-menu-group]')],links=[...root.querySelectorAll('[data-category]')];
if(input){root.querySelector('.menu-tools').hidden=false;const filter=()=>{const q=input.value.trim().toLocaleLowerCase();let total=0;groups.forEach(group=>{let n=0;group.querySelectorAll('.kc-dish').forEach(d=>{d.hidden=!!q&&!d.dataset.search.includes(q);if(!d.hidden)n++;});group.hidden=n===0;group.querySelectorAll('.kc-subheading').forEach(h=>h.hidden=!!q);total+=n;});clear.hidden=!q;status.hidden=!q;status.textContent=total+' '+(total===1?'dish':'dishes')+' found';empty.hidden=total!==0;};input.addEventListener('input',filter);clear.addEventListener('click',()=>{input.value='';filter();input.focus();});const reset=()=>{if(input.value){input.value='';filter();}};root.querySelectorAll('a[href^="#kc-"]').forEach(a=>a.addEventListener('click',reset));}
function setActive(id){links.forEach(a=>{if(a.getAttribute('href')==='#'+id)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});}
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){setActive(entry.target.id);break;}},{rootMargin:'-12% 0px -65% 0px',threshold:0});groups.forEach(g=>observer.observe(g));}
links.forEach(a=>a.addEventListener('click',()=>setActive(a.getAttribute('href').slice(1))));})();